:root {
  /* Colors */
  --color-fog-canvas: #f7f7f7;
  --color-paper-white: #ffffff;
  --color-ash-tile: #eeeded;
  --color-graphite-ink: #2e2e2e;
  --color-slate-caption: #000000b8;
  --color-mist-hint: #00000052;
  --color-dove-hairline: #00000014;
  --color-signal-blue: #207dff;
  --color-sand-tag: #b5801a;
  --color-forest-mark: #0f8f40;
  --color-sunbeam-marker: #e8bd3b80;
  --color-sprout-marker: #31d86980;

  /* Typography — Font Families */
  --font-instrument-sans: "Instrument Sans", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-inter: "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-georgia: Georgia, ui-serif, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.36;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.5;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 18px;
  --leading-subheading: 1.5;
  --tracking-subheading: -0.36px;
  --text-heading-sm: 25.5px;
  --leading-heading-sm: 1.3;
  --tracking-heading-sm: 0px;
  --text-heading: 32px;
  --leading-heading: 1.3;
  --tracking-heading: 0px;
  --text-heading-lg: 36px;
  --leading-heading-lg: 1.15;
  --tracking-heading-lg: -0.54px;
  --text-display: 48px;
  --leading-display: 1.3;
  --tracking-display: -1.58px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-3: 3px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-48: 48px;
  --spacing-60: 60px;
  --spacing-80: 80px;
  --spacing-128: 128px;

  /* Layout */
  --layout-max-width: 1396px;
  --layout-section-gap: 128px;
  --layout-card-padding: 16px;
  --layout-element-gap: 8px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-sm-2: 3px;
  --radius-md: 4px;
  --radius-md-2: 6px;
  --radius-lg: 8px;
  --radius-lg-2: 10px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-small-elements: 2px;
  --radius-badges: 3px;
  --radius-inputs: 4px;
  --radius-tags: 6px;
  --radius-inner-tiles: 6px;
  --radius-nav: 8px;
  --radius-small-cards: 8px;
  --radius-buttons: 10px;
  --radius-cards: 12px;
  --radius-images: 0px;
  --radius-pills: 9999px;
  --radius-avatars: 9999px;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.08) 0px 0px 0px 1px inset;
  --shadow-subtle-2: rgba(0, 0, 0, 0.08) -1px 0px 0px 0px inset;
  --shadow-sm: rgba(15, 15, 15, 0.1) 0px 0px 0px 1px, rgba(15, 15, 15, 0.1) 0px 2px 4px 0px;
  --shadow-sm-2: rgba(0, 0, 0, 0.08) 0px -1px 0px 0px inset;
  --shadow-md: rgba(0, 0, 0, 0.1) 0px 0px 0px 1px, rgba(0, 0, 0, 0.16) 0px 8px 20px 0px;
  --shadow-lg: rgba(0, 0, 0, 0.1) 0px 0px 0px 1px, rgba(0, 0, 0, 0.16) 0px 12px 28px 0px, rgba(0, 0, 0, 0.08) 0px 2px 6px 0px;

  /* Surfaces */
  --surface-fog-canvas: #f7f7f7;
  --surface-paper-white: #ffffff;
  --surface-ash-tile: #eeeded;
  --surface-graphite-ink: #2e2e2e;
}

